# owner: platform
import unittest
from datetime import date

from rosterkit.errors import ProjectError
from rosterkit.models import Mark, Student
from rosterkit.notices import build_notice

PUPIL = Student("1", "Last", "First", "A")

def _mark(number, status="absent", owner="1"):
    return Mark(owner, date(2026, 9, number), status)

class NoticeTests(unittest.TestCase):
    def test_lists_sorted_absences(self):
        marks = [_mark(5), _mark(2), _mark(3, "present")]
        self.assertEqual(
            build_notice(PUPIL, marks),
            "First Last missed 2 day(s): "
            "2026-09-02, 2026-09-05."
        )

    def test_foreign_mark(self):
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [_mark(2, owner="9")])

    def test_no_absences(self):
        with self.assertRaises(ProjectError):
            build_notice(PUPIL, [_mark(2, "late")])
